// Ordinary browser UI mirror of the Rust rule in kernel.rs:
// can_purchase(balance, stock) == balance >= 150 && stock > 0
// This is a UI mirror only; it is not a binding or a proof of the Rust code.

const MINIMUM_BALANCE = 150;

function canPurchase(balance, stock) {
  return balance >= MINIMUM_BALANCE && stock > 0;
}

// Reads a number input as a non-negative integer; invalid or empty input is 0.
function readAmount(input) {
  const raw = input.value.trim();
  if (raw === "") {
    return 0;
  }
  const value = Number(raw);
  if (!Number.isFinite(value) || value < 0) {
    return 0;
  }
  return Math.floor(value);
}

const form = document.getElementById("purchase-form");
const balanceInput = document.getElementById("balance");
const stockInput = document.getElementById("stock");
const result = document.getElementById("result");

form.addEventListener("submit", (event) => {
  event.preventDefault();

  const balance = readAmount(balanceInput);
  const stock = readAmount(stockInput);

  result.textContent = canPurchase(balance, stock) ? "Allowed" : "Refused";
});
